import { useEffect, useState } from "react";
import axios from "axios";
function DepartmentList() {
  const [department, setDepartment] = useState([]);
  const [employee, setEmpployee] = useState([]);
  useEffect(() => {
    const fetchData = async () => {
      const deptRespone = await axios.get("http://localhost:9999/departments");
      setDepartment(deptRespone.data);

      const empRespone = await axios.get("http://localhost:9999/employees");
      setEmpployee(empRespone.data);
    };
    fetchData();
  }, []);

  //get manager by managerId
  const getManagerName = (managerId) => {
    const manager = employee.find((emp) => emp.id === managerId);
    if (manager) {
      return manager.fullname;
    } else {
      return "";
    }
  };

  const handleViewClick = (departmentId) => {
    console.log("Mã Phòng ban:", departmentId);
  };

  return (
    <div>
      <h2>COMPANY MANAGERMENT</h2>
      <h3>Department List</h3>

      <table>
        <tr>
          <td>DepName</td>
          <td>Manager</td>
          <td>Employee</td>
        </tr>

        <tr>
          <td></td>
          <td></td>
          <td>Employee</td>
        </tr>
      </table>
    </div>
  );
}
export default DepartmentList;
